{
  "name": "Timepix4探测器控制器",
  "name_en": "Timepix4 Detector Controller",
  "manufacturer": "",
  "description": "用于控制 Timepix4 像素探测系统的硬件控制器，可执行偏置电源开关、快门开闭与触发配置、计时器复位与同步，并读取本地/远端/FPGA 温度、湿度、压力及风扇转速等运行状态。适用于探测器上电准备、曝光控制和实验运行监测。",
  "description_en": "A hardware controller for a Timepix4 pixel detector system. It manages the bias supply, shutter opening/closing and trigger configuration, timer reset and synchronization, and reads operating conditions such as local/remote/FPGA temperature, humidity, pressure, and fan speeds. It is used for detector preparation, exposure control, and runtime monitoring in experiments.",
  "actions": [
    {
      "action_name": "auto-setBiasSupplyEnable",
      "description": "启用或禁用探测器偏置电源。",
      "description_en": "Enable or disable the detector bias supply."
    },
    {
      "action_name": "auto-prepare",
      "description": "执行探测器控制器的准备流程，使系统进入可运行状态。",
      "description_en": "Run the controller preparation procedure to bring the detector system into an operational state."
    },
    {
      "action_name": "auto-resetTimers",
      "description": "将系统内部计时器复位为零。",
      "description_en": "Reset the internal system timers to zero."
    },
    {
      "action_name": "auto-restartTimers",
      "description": "重启并同步控制器与探测器计时器，以对齐时间戳。",
      "description_en": "Restart and synchronize the controller and detector timers so timestamps are aligned."
    },
    {
      "action_name": "auto-openShutter",
      "description": "立即打开探测器快门并保持开启。",
      "description_en": "Immediately open the detector shutter and keep it open."
    },
    {
      "action_name": "auto-closeShutter",
      "description": "立即关闭探测器快门。",
      "description_en": "Immediately close the detector shutter."
    },
    {
      "action_name": "auto-setShutterTriggerConfig",
      "description": "设置快门触发参数，包括模式、开启时长、频率、计数和延时。",
      "description_en": "Configure shutter triggering parameters, including mode, open duration, frequency, count, and delay."
    }
  ],
  "tag_hints": [
    "Timepix4 pixel detector",
    "radiation detection",
    "detector bias supply",
    "shutter trigger control",
    "timer synchronization",
    "environmental monitoring",
    "FPGA temperature monitoring"
  ]
}

